#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include "picotls.h"
#include "picotls/asn1.h"
#include "picotls/minicrypto.h"

void log_printf(void *ctx, const char *format, ...)
{
    (void)ctx;
    (void)format;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(fsize);
    fread(data, 1, fsize, f);
    fclose(f);

    ptls_minicrypto_log_ctx_t ctx = {NULL, log_printf};

    /* Simulate the fuzzer logic */
    if (fsize < 2) return 0;
    size_t bytes_max = (data[0] << 8) + data[1];
    if (bytes_max == 0) return 0;
    if (bytes_max > fsize - 2) bytes_max = fsize - 2;

    uint8_t *bytes = malloc(bytes_max);
    memcpy(bytes, data + 2, bytes_max);

    ptls_asn1_validation(bytes, bytes_max, &ctx);

    free(bytes);
    free(data);
    return 0;
}
